@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/geist-mono";

/* Faithful mode: warm paper page (#f5f1ee), white cards, black text, orange (#ff5e2b) CTAs. */
:root {
  --background: oklch(0.955 0.006 60);
  --foreground: oklch(0.1 0 0);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.1 0 0);
  --popover: oklch(1 0 0);
  --popover-foreground: oklch(0.1 0 0);
  --primary: oklch(0.679 0.208 38);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.917 0.005 60);
  --secondary-foreground: oklch(0.1 0 0);
  --muted: oklch(0.917 0.005 60);
  --muted-foreground: oklch(0.38 0.01 20);
  --accent: oklch(0.917 0.005 60);
  --accent-foreground: oklch(0.1 0 0);
  --destructive: oklch(0.577 0.22 27);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0 0 0 / 30%);
  --input: oklch(0 0 0 / 30%);
  --ring: oklch(0.679 0.208 38);
  --highlight: oklch(0.79 0.17 70);
  --highlight-foreground: oklch(0.1 0 0);
  --glow: oklch(0.72 0.19 45);
  --chart-1: oklch(0.679 0.208 38);
  --chart-2: oklch(0.79 0.17 70);
  --chart-3: oklch(0.64 0.24 28);
  --chart-4: oklch(0.52 0.23 265);
  --chart-5: oklch(0.65 0.015 30);
  --sidebar: oklch(0.955 0.006 60);
  --sidebar-foreground: oklch(0.1 0 0);
  --sidebar-primary: oklch(0.679 0.208 38);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.917 0.005 60);
  --sidebar-accent-foreground: oklch(0.1 0 0);
  --sidebar-border: oklch(0 0 0 / 15%);
  --sidebar-ring: oklch(0.679 0.208 38);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: var(--typeface-body);
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.5rem;
  --page-width: 90rem;
  --page-gutter: 1.25rem;
  --section-y: 6.5rem;
}

/* Dark sibling: black page, warm graphite cards (#241f1f), white text. */
.dark {
  --background: oklch(0 0 0);
  --foreground: oklch(1 0 0);
  --card: oklch(0.25 0.006 20);
  --card-foreground: oklch(1 0 0);
  --popover: oklch(0.25 0.006 20);
  --popover-foreground: oklch(1 0 0);
  --primary: oklch(0.679 0.208 38);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.25 0.006 20);
  --secondary-foreground: oklch(1 0 0);
  --muted: oklch(0.25 0.006 20);
  --muted-foreground: oklch(0.65 0.015 30);
  --accent: oklch(1 0 0 / 10%);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.66 0.2 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(1 0 0 / 30%);
  --input: oklch(1 0 0 / 30%);
  --ring: oklch(0.679 0.208 38);
  --highlight: oklch(0.79 0.17 70);
  --highlight-foreground: oklch(0.1 0 0);
  --glow: oklch(0.72 0.19 45);
  --chart-1: oklch(0.679 0.208 38);
  --chart-2: oklch(0.79 0.17 70);
  --chart-3: oklch(0.64 0.24 28);
  --chart-4: oklch(0.6 0.2 265);
  --chart-5: oklch(0.65 0.015 30);
  --sidebar: oklch(0.14 0.004 20);
  --sidebar-foreground: oklch(1 0 0);
  --sidebar-primary: oklch(0.679 0.208 38);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.25 0.006 20);
  --sidebar-accent-foreground: oklch(1 0 0);
  --sidebar-border: oklch(1 0 0 / 15%);
  --sidebar-ring: oklch(0.679 0.208 38);
}
